const ARCHIVE_LF = 10;
const ARCHIVE_CR = 13;

function decodeArchiveLine(parts, length, removeTrailingCR, decoder) {
  if (removeTrailingCR && length > 0) {
    const lastPart = parts[parts.length - 1];
    if (lastPart[lastPart.length - 1] === ARCHIVE_CR) {
      length -= 1;
    }
  }

  if (length === 0) {
    return "";
  }

  if (parts.length === 1) {
    return decoder.decode(parts[0].subarray(0, length));
  }

  const bytes = new Uint8Array(length);
  let offset = 0;

  for (const part of parts) {
    const count = Math.min(part.length, length - offset);
    if (count > 0) {
      bytes.set(part.subarray(0, count), offset);
      offset += count;
    }
    if (offset === length) {
      break;
    }
  }

  return decoder.decode(bytes);
}

function invalidArchiveRecord(line) {
  const error = new SyntaxError("Invalid JSON record at line " + line);
  error.code = "INVALID_RECORD";
  error.line = line;
  return error;
}

async function* readArchive(chunks) {
  let sourceIterator = null;
  let sourceFinished = false;
  let sourceReturned = false;
  let hasPrimaryFailure = false;

  let currentChunk = null;
  let chunkOffset = 0;
  let lineParts = [];
  let lineLength = 0;
  let lineNumber = 1;

  const decoder = new TextDecoder("utf-8");

  function appendChunkRange(start, end, copy) {
    if (end <= start) {
      return;
    }

    const part = currentChunk.subarray(start, end);
    lineParts.push(copy ? new Uint8Array(part) : part);
    lineLength += end - start;
  }

  function finishLine(terminatedByLF) {
    const record = {
      parts: lineParts,
      length: lineLength,
      line: lineNumber,
      removeTrailingCR: terminatedByLF
    };

    lineParts = [];
    lineLength = 0;

    if (terminatedByLF) {
      lineNumber += 1;
    }

    return record;
  }

  async function readLine() {
    for (;;) {
      if (currentChunk !== null) {
        if (chunkOffset < currentChunk.length) {
          const newlineAt = currentChunk.indexOf(ARCHIVE_LF, chunkOffset);

          if (newlineAt !== -1) {
            appendChunkRange(chunkOffset, newlineAt, false);
            chunkOffset = newlineAt + 1;

            const record = finishLine(true);

            if (chunkOffset === currentChunk.length) {
              currentChunk = null;
              chunkOffset = 0;
            }

            return record;
          }

          appendChunkRange(chunkOffset, currentChunk.length, true);
        }

        currentChunk = null;
        chunkOffset = 0;
      }

      if (sourceFinished) {
        return lineLength === 0 ? null : finishLine(false);
      }

      const step = await sourceIterator.next();

      if (step.done) {
        sourceFinished = true;
      } else {
        currentChunk = step.value;
        chunkOffset = 0;
      }
    }
  }

  try {
    sourceIterator = chunks[Symbol.asyncIterator]();

    for (;;) {
      let value;

      {
        const record = await readLine();

        if (record === null) {
          return;
        }

        const text = decodeArchiveLine(
          record.parts,
          record.length,
          record.removeTrailingCR,
          decoder
        );

        if (text.trim().length === 0) {
          continue;
        }

        try {
          value = JSON.parse(text);
        } catch (error) {
          if (error instanceof SyntaxError) {
            throw invalidArchiveRecord(record.line);
          }
          throw error;
        }
      }

      yield value;
    }
  } catch (error) {
    hasPrimaryFailure = true;
    throw error;
  } finally {
    if (sourceIterator !== null && !sourceFinished && !sourceReturned) {
      sourceReturned = true;

      try {
        const close = sourceIterator.return;
        if (typeof close === "function") {
          await close.call(sourceIterator);
        }
      } catch (error) {
        if (!hasPrimaryFailure) {
          throw error;
        }
      }
    }
  }
}
